1	<?php
2	use BackWPup\Utils\BackWPupHelpers;
3	
4	if ( ! defined( 'ABSPATH' ) ) {
5	    exit;
6	}
7	
8	/**
9	 * @var string  $type           The type of alert. Values: "pro", "alert", "danger", "default". Default: "default".
10	 * @var string  $content        The content. Default: "".
11	 * @var string  $content2       Optional. A second line of content. Default: "".
12	 * @var string  $font           Optional. The font size. Values: "xs", "small", "medium". Default: null.
13	 * @var string  $children       Optional. Children component to display. Must fit a /part/ template. Default: null.
14	 */
15	
16	# Type
17	$types = ["pro", "alert", "danger", "default","success"];
18	$type = isset($type) && in_array($type, $types) ? $type : "default";
19	switch ($type) {
20	  case "pro":
21	    $block_style = "bg-secondary-lighter text-primary-darker";
22	    $icon = "pro";
23	    break;
24	  case "alert":
25	    $block_style = "bg-alert-light text-alert";
26	    $icon = "alert";
27	    break;
28	  case "danger":
29	    $block_style = "bg-danger-light text-danger";
30	    $icon = "alert";
31	    break;
32	  case "success":
33	    $block_style = "bg-secondary-lighter text-primary-darker";
34	    $icon = "circle-check";
35	    break;
36	
37	  default:
38	    $block_style = "bg-white text-primary-darker";
39	    $icon = "info";
40	    break;
41	}
42	
43	# Font
44	$font = $font ?? "medium";
45	$font_sizes = [
46	  "xs" => "text-xs",
47	  "small" => "text-sm",
48	  "medium" => "text-base",
49	];
50	$font_size = array_key_exists($font, $font_sizes) ? $font_sizes[$font] : $font_sizes['medium'];
51	
52	$dismiss_icon = $dismiss_icon ?? false;
53	?>
54	<div class="flex items-center gap-2 p-4 rounded <?php echo esc_attr( $block_style ); ?>">
55	  <div class="shrink-0">
56	    <?php BackWPupHelpers::component("icon", ["name" => $icon, "size" => "large"]); ?>
57	  </div>
58	  <div class="flex flex-col gap-1 flex-1">
59	    <p class="<?php echo esc_attr( $font_size ); ?> font-medium">
60	      <?php echo wp_kses_post( $content ?? '' ); ?>
61	    </p>
62	    <?php if (isset($content2)) : ?>
63	      <p class="<?php echo esc_attr( BackWPupHelpers::clsx( "mt-2", $font_size ) ); ?> font-medium">
64	        <?php echo wp_kses_post( $content2 ); ?>
65	      </p>
66	    <?php endif; ?>
67	    <?php isset($children) && BackWPupHelpers::children($children); ?>
68	  </div>
69		<?php if ($dismiss_icon) : ?>
70	    <div class="shrink-0 cursor-pointer ml-auto dismiss-icon">
71			<?php BackWPupHelpers::component("icon", ["name" => "close", "size" => "small"]); ?>
72	    </div>
73	    <?php endif; ?>
74	</div>
