15	 *
16	 * @group Tracking
17	 */
18	class TrackStartJobTest extends TestCase {
19	
20		public function set_up(): void {
21			parent::set_up();
22			\BackWPup::set_is_pro( true );
23		}
24	
25		public function tear_down(): void {
26			\BackWPup::set_is_pro( false );
27			delete_site_option( 'backwpup_license_email' );
28			parent::tear_down();
29		}
30	
31		/**
32		 * @dataProvider configTestData
33		 */
34		public function testShouldDoAsExpected( array $config, array $expected ): void {
35	        $was_pro = \BackWPup::is_pro();
36	        if ( isset( $config['is_pro'] ) ) {
37	            \BackWPup::set_is_pro( $config['is_pro'] );
38	        }
39	        
40			$user_id = self::factory()->user->create( [ 'user_email' => $config['email'] ] );
41			wp_set_current_user( $user_id );
42	
43			if ( isset( $config['backwpup_license_email'] ) && '' !== $config['backwpup_license_email'] ) {
44				update_site_option( 'backwpup_license_email', $config['backwpup_license_email'] );
45			}
46	
47			$optin          = $this->createMock( Optin::class );
48			$mixpanel       = $this->createMock( MixpanelTracking::class );
49			$option_adapter = $this->createMock( OptionAdapter::class );
50	
51			$tracking = new Tracking( $optin, $mixpanel, $option_adapter );
52	
53			if ( ! $expected['status'] ) {
54				$optin->expects( $this->once() )
55					->method( 'can_track' )
56					->willReturn( false );
57	
58				$tracking->track_start_job( $config['job_data'], $config['backup_trigger'] );
59	
60				return;
61			}
62	
63			$optin->expects( $this->once() )
64				->method( 'can_track' )
65				->willReturn( true );
66	
67			$mixpanel->expects( $this->once() )
68				->method( 'identify' )
69				->with( $config['email'] );
70	
71			$option_adapter->method( 'defaults_job' )
72				->willReturn( $config['defaults_job'] );
73	
74			$mixpanel->expects( $this->once() )
75				->method( 'track' )
76				->with( 'Scheduled Backup Job Started', $expected['job_data'], 'bwu_mixpanel_send_event' );
77	
78			$tracking->track_start_job( $config['job_data'], $config['backup_trigger'] );
79	        
80	        if ( isset( $config['is_pro'] ) ) {
81	            \BackWPup::set_is_pro( $was_pro );
82	        }
83		}
84	}
